using System.Data;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Threading;
namespace SchoolApp;
public class BookingWindow:Window
{
 public BookingWindow(int id){Ui.Setup(this,"Запись клиента на услугу");Width=600;Height=510;var p=new StackPanel{Margin=new Thickness(16)};Content=p;p.Children.Add(Ui.Header("Запись клиента"));var r=Db.Query("SELECT Title,DurationInSeconds FROM Service WHERE ID=@id",("@id",id)).Rows[0];int seconds=Convert.ToInt32(r["DurationInSeconds"]);p.Children.Add(new TextBlock{Text=$"{r["Title"]}\nДлительность: {seconds/60.0:0.##} минут",TextWrapping=TextWrapping.Wrap});p.Children.Add(new TextBlock{Text="Клиент",Margin=new Thickness(4,12,4,4)});var clients=new ComboBox{ItemsSource=Db.Query("SELECT ID, CONCAT(LastName,' ',FirstName,' ',Patronymic) AS FullName FROM Client ORDER BY LastName,FirstName").DefaultView,DisplayMemberPath="FullName",SelectedValuePath="ID",Margin=new Thickness(4)};p.Children.Add(clients);p.Children.Add(new TextBlock{Text="Дата",Margin=new Thickness(4,12,4,4)});var date=new DatePicker{SelectedDate=DateTime.Today,Margin=new Thickness(4)};p.Children.Add(date);var time=Ui.Field(p,"Время начала (ЧЧ:ММ)","12:00");time.PreviewTextInput+=(_,e)=>e.Handled=e.Text.Any(c=>!char.IsAsciiDigit(c)&&c!=':');DataObject.AddPastingHandler(time,(_,e)=>{if(e.DataObject.GetData(typeof(string)) is not string s||s.Any(c=>!char.IsAsciiDigit(c)&&c!=':'))e.CancelCommand();});var end=new TextBlock{Margin=new Thickness(4)};p.Children.Add(end);DateTime Start(){if(!date.SelectedDate.HasValue||!TimeSpan.TryParseExact(time.Text,"hh\\:mm",CultureInfo.InvariantCulture,out var t))throw new Exception("Выберите дату и введите время в формате ЧЧ:ММ (00:00–23:59).");return date.SelectedDate.Value.Date+t;}void Refresh(){try{end.Text="Окончание: "+Start().AddSeconds(seconds).ToString("dd.MM.yyyy HH:mm");}catch{end.Text="Введите корректные дату и время";}}time.TextChanged+=(_,_)=>Refresh();date.SelectedDateChanged+=(_,_)=>Refresh();Refresh();p.Children.Add(Ui.Button("Сохранить запись",()=>{if(clients.SelectedValue==null)throw new Exception("Выберите клиента.");Db.Execute("INSERT ClientService(ClientID,ServiceID,StartTime) VALUES(@c,@s,@t)",("@c",clients.SelectedValue),("@s",id),("@t",Start()));MessageBox.Show("Клиент записан.","Готово");DialogResult=true;}));}
}
public class UpcomingWindow:Window
{
 readonly DispatcherTimer timer=new(){Interval=TimeSpan.FromSeconds(30)};readonly StackPanel rows=new();readonly TextBlock status=new(){Margin=new Thickness(4)};
 public UpcomingWindow(){Ui.Setup(this,"Ближайшие записи — сегодня и завтра");Width=900;Height=640;var root=new DockPanel{Margin=new Thickness(16)};Content=root;var top=new StackPanel();top.Children.Add(Ui.Header("Сегодня и завтра"));top.Children.Add(status);top.Children.Add(Ui.Button("Обновить",Refresh));DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);root.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});timer.Tick+=(_,_)=>Refresh();Loaded+=(_,_)=>{Refresh();timer.Start();};Closed+=(_,_)=>timer.Stop();}
 void Refresh(){try{var now=DateTime.Now;var data=Db.Query("SELECT s.Title,c.LastName,c.FirstName,c.Patronymic,c.Email,c.Phone,cs.StartTime FROM ClientService cs JOIN Service s ON s.ID=cs.ServiceID JOIN Client c ON c.ID=cs.ClientID WHERE cs.StartTime>=@today AND cs.StartTime<@end ORDER BY cs.StartTime,cs.ID",("@today",now.Date),("@end",now.Date.AddDays(2)));rows.Children.Clear();foreach(DataRow r in data.Rows){var t=(DateTime)r["StartTime"];var remaining=t-now;var p=new StackPanel{Margin=new Thickness(12),Background=Ui.Green};p.Children.Add(new TextBlock{Text=r["Title"].ToString(),FontSize=18,TextWrapping=TextWrapping.Wrap});p.Children.Add(new TextBlock{Text=$"{r["LastName"]} {r["FirstName"]} {r["Patronymic"]}\n{r["Email"]}    {r["Phone"]}\nНачало: {t:dd.MM.yyyy HH:mm}"});p.Children.Add(new TextBlock{Text=remaining.TotalSeconds<=0?"Услуга уже началась":$"До начала: {(int)remaining.TotalHours} ч {remaining.Minutes} мин",Foreground=remaining.TotalSeconds>0&&remaining.TotalHours<1?Brushes.Red:Brushes.Black});rows.Children.Add(p);}status.Text=$"Записей: {data.Rows.Count}. Обновлено: {now:HH:mm:ss}. Интервал: 30 секунд.";}catch(Exception e){status.Text="Ошибка обновления: "+e.Message;}}
}
